        <svg class="mx-auto w-[80px] sm:w-[30px] md:w-[130px] h-auto mb-2 md:mb-4"
            viewBox="0 0 287 282" 
            fill="none" 
            xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink">
            <rect width="287" height="282" fill="url(#pattern0_920_535)"/>
            <defs>
            <pattern id="pattern0_920_535" patternContentUnits="objectBoundingBox" width="1" height="1">
            <use xlink:href="#image0_920_535" transform="scale(0.00190476 0.00193853)"/>
            </pattern>
