        <p class="font-body text-body-small text-neutral-normal leading-relaxed pb-12 text-center">A Journey Through Teyvat is a fan-made website. <br>Website is not affiliated with miHoYo, all assets files are property of their original owners.</p>

    </div>

    <script>
        document.addEventListener("DOMContentLoaded", () => {
            const sections = document.querySelectorAll('section[id]'); // Cukup deklarasikan 1 kali saja
            const navLinks = document.querySelectorAll('.nav-link');
            const mobileMenuButton = document.getElementById('mobile-menu-button');
            const navMenu = document.getElementById('nav-menu');

            // 1. Logika Toggle Menu Mobile
            mobileMenuButton.addEventListener('click', () => {
                navMenu.classList.toggle('hidden');
                navMenu.classList.toggle('flex'); // Typo nav.Menu diperbaiki
            });

            // Menutup menu mobile saat link diklik
            navLinks.forEach(link => {
                link.addEventListener('click', () => {
                    if (!navMenu.classList.contains('hidden')) {
                        navMenu.classList.add('hidden');
                        navMenu.classList.remove('flex');
                    }
                });
            });

            // 2. Logika Intersection Observer
            const observer = new IntersectionObserver(
                (entries) => {
                    entries.forEach((entry) => {
                        if (entry.isIntersecting) {
                            navLinks.forEach((link) => {
                                link.classList.remove('active');
                            });
            
                            const activeLink = document.querySelector(
                                `.nav-link[data-section="${entry.target.id}"]`
                            );
            
                            if (activeLink) {
                                activeLink.classList.add('active');
                            }
                        }
                    });
                },
                {
                    threshold: 0.5
                }
            );
            
            sections.forEach((section) => observer.observe(section));
        });
    </script>
</body>
